command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="108cedb5c17a1229604dc6f7a43fbc7c2eb775ab"
$candidate="ff9641d05645266ce639fddff97fdb82f014cc3e"
$branch="work/shell-provider-thumbnail-20261007"
$beforeHash="ce6ef976c28b0f513b008bfb0b763458a7742f6a89749e953261f521b3b36173"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "provider thumbnail fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before provider thumbnail validation"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "provider thumbnail candidate mismatch"}
$dirty=@(& git status --porcelain=v1 -uall)
if($dirty.Count -ne 0){$dirty|%{Write-Host ("UNEXPECTED_WORKTREE="+$_)};throw "persistent checkout dirty"}
$before=Join-Path $repo "logs\shell-provider-thumbnail\shell-provider-thumbnail-before.bmp"
if(-not(Test-Path -LiteralPath $before -PathType Leaf)){throw "accepted provider thumbnail BEFORE missing"}
if((Get-FileHash -Algorithm SHA256 $before).Hash.ToLowerInvariant() -ne $beforeHash){throw "provider thumbnail BEFORE hash changed"}
& git switch --detach $candidate
if($LASTEXITCODE -ne 0){throw "provider thumbnail candidate checkout failed"}
& .\build.bat Release
if($LASTEXITCODE -ne 0){throw "provider thumbnail Release build failed"}
& python -X utf8 tests\winui\test_shell_provider_thumbnail_gui.py --configuration Release --capture after --expect-provider-thumbnail
if($LASTEXITCODE -ne 0){throw "provider thumbnail focused GUI failed"}
$after=Join-Path $repo "logs\shell-provider-thumbnail\shell-provider-thumbnail-after.bmp"
if(-not(Test-Path -LiteralPath $after -PathType Leaf)){throw "provider thumbnail AFTER missing"}
$evidence=Join-Path $repo "logs\remote-evidence"
New-Item -ItemType Directory -Force -Path $evidence|Out-Null
Copy-Item -LiteralPath $before -Destination (Join-Path $evidence "shell-provider-thumbnail-before.bmp") -Force
Copy-Item -LiteralPath $after -Destination (Join-Path $evidence "shell-provider-thumbnail-after.bmp") -Force
Write-Host ("SHELL_PROVIDER_THUMBNAIL_AFTER_SHA256="+(Get-FileHash -Algorithm SHA256 $after).Hash.ToLowerInvariant())
& git switch main
if($LASTEXITCODE -ne 0){throw "failed to restore main after provider thumbnail validation"}
& git merge --ff-only origin/main
if($LASTEXITCODE -ne 0){throw "failed to fast-forward main after provider thumbnail validation"}
Write-Host "SHELL_PROVIDER_THUMBNAIL_VALIDATION=PASS"
